          "note": "胡塞武裝持續攻擊沙烏地石油設施,沙烏地阿美10/22通知達蘭總部員工撤離;布蘭特原油收113.17美元(+4.0%),創5月4日以來最高收盤,WTI收99.47美元(+2.4%),10/23盤中WTI續漲2.47%至101.93美元。另有利比亞Hamada、Tahara油田因管線閥門關閉減產,荷莫茲海峽船隻遭襲加深供應疑慮。"
