      "title": "美伊和平協議",
      "summary": "4月美伊簽署兩週停火及霍爾木茲海峽安全通行備忘錄，惟7月起因伊朗攻擊未依協議路線之商船而形同破局；9月雙方爆發「油輪戰」，美軍打擊伊朗油輪、伊朗則攻擊美方相關船隻並一度威脅封鎖海峽，沙特輸油管線亦遭波及，牽動全球油價與通膨前景。",
